function parseGlossary(text){
  return String(text||'').split(/\n+/).map(function(l){
    l=l.trim(); if(!l) return null;
    var i=l.indexOf(':'), j=l.indexOf('：');
    var pos=-1;
    if(i>=0&&(j<0||i<j)) pos=i; else if(j>=0) pos=j;
    if(pos<=0||pos>=l.length-1) return null;
    return {term:l.slice(0,pos).trim(), def:l.slice(pos+1).trim()};
  }).filter(function(x){return x && x.term && x.def;});
}
function sortTerms(items, order){
  var arr=items.slice();
  order=String(order||'字母序');
  if(order.indexOf('字母')>=0){
    arr.sort(function(a,b){ return a.term<b.term?-1:(a.term>b.term?1:0); });
  } else if(order.indexOf('长度')>=0){
    arr.sort(function(a,b){ return a.term.length-b.term.length || (a.term<b.term?-1:1); });
  }
  return arr;
}
function buildGlossary(o){
  o=o||{};
  var items=parseGlossary(o.text);
  var order=String(o.order||'字母序');
  var fmt=String(o.format||'表格');
  var sorted=sortTerms(items, order);
  var lines=[];
  lines.push('# 术语表（共 '+items.length+' 条）');
  lines.push('');
  if(!items.length){
    lines.push('（暂无有效词条，请按「术语: 定义」每行一条填写）');
  } else if(fmt.indexOf('列表')>=0){
    sorted.forEach(function(x){ lines.push('- **'+x.term+'**：'+x.def); });
  } else {
    lines.push('| 术语 | 定义 |');
    lines.push('| --- | --- |');
    sorted.forEach(function(x){ lines.push('| '+x.term+' | '+x.def.replace(/\|/g,'/')+' |'); });
  }
  return {count:items.length, markdown:lines.join('\n')};
}
var EXPORTS={parseGlossary:parseGlossary, sortTerms:sortTerms, buildGlossary:buildGlossary};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.GlossaryForgePure = EXPORTS; }
